// Contract and arbitration data for the roster builder, league-wide. None
// of this is in the MLB Stats API: lib/contracts-data.json is generated by
// scripts/update-contracts.mjs from FanGraphs RosterResource (guaranteed
// deals, options, arb years, pre-arb free-agency timing, dead money) and MLB
// Trade Rumors' arbitration projections. Re-run it as deals are signed,
// options are decided, and arbitration figures settle. Every figure is an
// estimate until a team's payroll is final.

import contractData from "./contracts-data.json";
import { FREE_AGENTS } from "./free-agents";

export const CONTRACT_SEASON = 2027;

// When lib/contracts-data.json was last regenerated.
export const CONTRACTS_UPDATED = contractData.updated;

// The 2026 league minimum. The 2027 figure depends on the new CBA, so
// pre-arb salaries are an estimate until that's settled.
export const PRE_ARB_SALARY_ESTIMATE = 780_000;

// What a 40-man player earns while in the minors on a split contract (2026
// CBA figures, used until the next CBA sets 2027's): less on a player's
// first major league contract, more on any later one.
export const MINOR_LEAGUE_SALARY_FIRST_CONTRACT = 63_600;
export const MINOR_LEAGUE_SALARY = 127_100;

// "signed" is a deal made inside the roster builder (a created player, a
// free agent, or an extension that replaces the current deal), not a real
// contract. "extended" is a real current deal plus a builder extension that
// starts after it.
export type ContractStatus =
  | "guaranteed"
  | "signed"
  | "extended"
  | "club-option"
  | "mutual-option"
  | "vesting-option"
  // The player decides on this season (a player option or a pending
  // opt-out); counted until he opts out.
  | "player-option"
  | "arbitration"
  | "pre-arb";

export type ContractInfo = {
  status: ContractStatus;
  // Salary for CONTRACT_SEASON — projected for arbitration players.
  salary: number;
  detail: string;
  freeAgentAfter?: number;
  // True when freeAgentAfter is the earliest possible year, estimated from
  // the MLB debut date rather than taken from a source.
  freeAgentEstimated?: boolean;
  // Salary for every guaranteed season, CONTRACT_SEASON on — used for
  // future-year payroll commitments. Absent for one-season figures
  // (arbitration, pre-arb, options).
  salaryBySeason?: Record<number, number>;
  // What declining an option costs (club and mutual options only). It's
  // owed even though the player leaves, so it stays on as dead money.
  buyout?: number;
  // Luxury-tax hit for CONTRACT_SEASON when it differs from the salary: a
  // guaranteed deal counts at its AAV, with deferred money at present value.
  cbt?: number;
  // How much of CONTRACT_SEASON's salary is deferred (paid in later years).
  deferred?: number;
  // FanGraphs' description of a real contract's deferrals.
  deferralNote?: string;
};

// Money a club pays for players no longer on its roster: cash owed in
// trades, released players, buyouts. Negative amounts are money coming in.
export type OtherPayment = { season: number; amount: number; description: string };

// Keyed by MLB player id.
const CONTRACTS = contractData.contracts as unknown as Record<string, ContractInfo>;

// Details the sources leave out, layered over the generated data.
const CONTRACT_OVERRIDES: Record<number, Partial<ContractInfo>> = {
  // Stanek's buyout (MLB Trade Rumors); FanGraphs lists the option only.
  592773: { detail: "$6M club option, $1M buyout", buyout: 1_000_000 },
};

// Free-agency year for pre-arb players, from FanGraphs.
const PRE_ARB_FREE_AGENT_AFTER = contractData.preArbFreeAgentAfter as Record<string, number>;

// Pre-arb players' prior-season salaries (FanGraphs) — clubs pay them a bit
// over the minimum, so these differ player to player.
const PRE_ARB_PRIOR_SALARY = contractData.preArbPriorSalary as Record<string, number>;

const OTHER_PAYMENTS = contractData.otherPayments as Record<string, OtherPayment[]>;

// Players whose contracts run out after this season: FanGraphs' list plus
// the Free Agents tab's (MLB Trade Rumors). Anyone with a CONTRACT_SEASON
// deal, option, or arbitration year in the data is still under control.
const IMPENDING_FREE_AGENT_IDS = new Set<number>([
  ...(contractData.freeAgents as number[]),
  ...FREE_AGENTS.map((player) => player.id),
]);

// The roster builder simulates CONTRACT_SEASON, so these players are left
// off every club's roster (they can be signed back as free agents).
export function isImpendingFreeAgent(playerId: number): boolean {
  return IMPENDING_FREE_AGENT_IDS.has(playerId) && !CONTRACTS[playerId];
}

// Players a club owes guaranteed CONTRACT_SEASON money (per FanGraphs) —
// including any missing from its MLB roster feed, like a player on the
// restricted list.
export function getContractedPlayerIds(teamId: number): number[] {
  return Object.entries(CONTRACTS)
    .filter(
      ([, contract]) =>
        (contract as ContractInfo & { teamId?: number }).teamId === teamId &&
        (contract.status === "guaranteed" || contract.status === "player-option")
    )
    .map(([id]) => Number(id));
}

export function getOtherPayments(teamId: number): OtherPayment[] {
  return OTHER_PAYMENTS[teamId] ?? [];
}

export type TaxAdjustment = { amount: number; description: string };

const TAX_ADJUSTMENTS = contractData.taxAdjustments as Record<string, TaxAdjustment[]>;

// Luxury-tax-only entries for CONTRACT_SEASON (e.g. AAV credits and debits
// when cash changed hands in a trade).
export function getTaxAdjustments(teamId: number): TaxAdjustment[] {
  return TAX_ADJUSTMENTS[teamId] ?? [];
}

// Player benefits count toward every club's luxury-tax payroll (FanGraphs'
// league-wide estimate).
export const PLAYER_BENEFITS_ESTIMATE: number = contractData.playerBenefits ?? 18_500_000;

// Each club's share of the CBA's $50M pre-arbitration bonus pool, which also
// counts toward the luxury-tax payroll.
export const PRE_ARB_BONUS_POOL_SHARE = Math.round(50_000_000 / 30);

// Free agency comes after six years of MLB service. Without service-time
// data, assume a player has been up continuously since debuting: a debut
// by mid-April counts that season as a full year. Any time spent in the
// minors since pushes the real date later, so this is the earliest it
// could be. A player who hasn't debuted can't reach six years before
// CONTRACT_SEASON + 5, even with a full season in the majors next year.
function estimateFreeAgentAfter(debutDate?: string): number {
  if (!debutDate) {
    return CONTRACT_SEASON + 5;
  }

  const debut = new Date(debutDate);
  const year = debut.getUTCFullYear();
  const isFullSeason = debut.getUTCMonth() < 3 || (debut.getUTCMonth() === 3 && debut.getUTCDate() <= 15);

  return year + (isFullSeason ? 5 : 6);
}

function preArbContract(playerId: number, debutDate?: string): ContractInfo {
  const known = PRE_ARB_FREE_AGENT_AFTER[playerId];
  const prior = PRE_ARB_PRIOR_SALARY[playerId];
  // At least last season's salary, and never under the minimum.
  const salary = Math.max(PRE_ARB_SALARY_ESTIMATE, prior ?? 0);

  return {
    status: "pre-arb",
    salary,
    detail:
      prior && prior > PRE_ARB_SALARY_ESTIMATE
        ? `Pre-arb · ${formatSalary(prior)} in ${CONTRACT_SEASON - 1}`
        : "Pre-arb · near league minimum",
    freeAgentAfter: known ?? estimateFreeAgentAfter(debutDate),
    freeAgentEstimated: known === undefined,
  };
}

// Any real player without a listed deal (on any club) is treated as
// pre-arb. Players created by hand (negative ids) have no known contract.
export function getContract(player: { id: number; debutDate?: string }): ContractInfo | null {
  const listed = CONTRACTS[player.id];
  if (listed) {
    return { ...listed, ...CONTRACT_OVERRIDES[player.id] };
  }

  return player.id > 0 ? preArbContract(player.id, player.debutDate) : null;
}

// Part of a builder deal's money paid after the fact, in equal installments
// over `payoutYears` seasons starting with `payoutStart`. It comes out of
// each season's salary in proportion to that salary.
export type Deferral = { total: number; payoutStart: number; payoutYears: number };

// A deal made in the roster builder: one salary per season, starting with
// `startSeason` (CONTRACT_SEASON unless it's an extension that begins after
// a player's current deal).
export type Signing = { salaries: number[]; startSeason?: number; deferral?: Deferral };

const SALARY_ROUNDING = 1_000;

// The CBA counts deferred money at present value for the luxury tax, using a
// federal interest rate set each year — about 4.5% lately. Approximate.
export const DEFERRAL_DISCOUNT_RATE = 0.045;

// A flat deal: the total split evenly across its seasons (to the nearest
// $1K, with the last season absorbing the remainder so the total is exact).
export function flatSalaries(total: number, years: number): number[] {
  const perSeason = Math.round(total / years / SALARY_ROUNDING) * SALARY_ROUNDING;
  const salaries = Array.from({ length: years }, () => perSeason);
  salaries[years - 1] = total - perSeason * (years - 1);
  return salaries;
}

function seasonSpan(start: number, end: number) {
  return start === end ? String(start) : `${start}–${String(end).slice(2)}`;
}

// Deferred money per season, proportional to each season's salary.
function deferredBySeason({ salaries, deferral }: Signing): number[] {
  const total = salaries.reduce((sum, salary) => sum + salary, 0);
  if (!deferral || total <= 0) {
    return salaries.map(() => 0);
  }
  return salaries.map((salary) => Math.round((deferral.total * salary) / total));
}

// The deal's luxury-tax AAV: money paid on time at face value plus the
// deferred payouts discounted back to the deal's first season.
export function signingTaxAav(signing: Signing): number {
  const start = signing.startSeason ?? CONTRACT_SEASON;
  const deferred = deferredBySeason(signing);
  const paidOnTime = signing.salaries.reduce((sum, salary, index) => sum + salary - deferred[index], 0);
  let presentValue = 0;

  if (signing.deferral && signing.deferral.payoutYears > 0) {
    const installment = signing.deferral.total / signing.deferral.payoutYears;
    for (let index = 0; index < signing.deferral.payoutYears; index += 1) {
      const season = signing.deferral.payoutStart + index;
      presentValue += installment / (1 + DEFERRAL_DISCOUNT_RATE) ** (season - start);
    }
  }

  return Math.round((paidOnTime + presentValue) / signing.salaries.length);
}

// A builder deal as a contract. One that starts after CONTRACT_SEASON (an
// extension) sits on top of the player's current contract, which still
// covers this season and any guaranteed years before the extension.
export function signedContract(signing: Signing, current: ContractInfo | null = null): ContractInfo {
  const { salaries, deferral } = signing;
  const start = signing.startSeason ?? CONTRACT_SEASON;
  const years = salaries.length;
  const total = salaries.reduce((sum, salary) => sum + salary, 0);
  const lastSeason = start + years - 1;
  const isEven = salaries.every((salary) => salary === salaries[0]);
  const schedule = isEven ? "" : ` · ${salaries.map((salary) => formatSalary(salary).replace(/^\$|M$/g, "")).join("/")}`;
  const deferralText = deferral
    ? ` · ${formatSalary(deferral.total)} deferred, paid ${seasonSpan(deferral.payoutStart, deferral.payoutStart + deferral.payoutYears - 1)}`
    : "";
  const dealDetail = `${years} yr / ${formatSalary(total)} (${seasonSpan(start, lastSeason)})${schedule}${deferralText}`;
  const newSeasons = Object.fromEntries(salaries.map((salary, index) => [start + index, salary]));
  const deferred = deferredBySeason(signing);
  const taxAav = signingTaxAav(signing);

  if (start > CONTRACT_SEASON && current) {
    const earlierSeasons = Object.fromEntries(
      Object.entries(current.salaryBySeason ?? {}).filter(([season]) => Number(season) < start)
    );
    return {
      ...current,
      status: "extended",
      detail: `${current.detail} · extended ${dealDetail}`,
      freeAgentAfter: lastSeason,
      freeAgentEstimated: false,
      salaryBySeason: { ...earlierSeasons, ...newSeasons },
    };
  }

  return {
    status: "signed",
    salary: salaries[0],
    detail: dealDetail,
    freeAgentAfter: lastSeason,
    salaryBySeason: newSeasons,
    ...(taxAav !== salaries[0] ? { cbt: taxAav } : {}),
    ...(deferred[0] > 0 ? { deferred: deferred[0] } : {}),
  };
}

// $30M, $7.5M, $2.75M, $780K — only trailing zeros after a decimal point are
// trimmed (a bare "30" must stay "30").
export function formatSalary(amount: number): string {
  if (amount === 0) {
    return "$0";
  }

  // Money coming in (e.g. cash received in a trade): "-$10.83M".
  if (amount < 0) {
    return `-${formatSalary(-amount)}`;
  }

  if (Math.abs(amount) >= 1_000_000) {
    const millions = (amount / 1_000_000).toFixed(2).replace(/\.?0+$/, "");
    return `$${millions}M`;
  }

  return `$${Math.round(amount / 1_000)}K`;
}
